const $ = (id) => document.getElementById(id);
const t = (key, ...args) => typeof T[state.lang][key] === 'function' ? T[state.lang][key](...args) : T[state.lang][key];

function scrollTo(id) {
  document.getElementById(id)?.scrollIntoView({ behavior: 'smooth' });
}

// ─── RENDER ENGINE ──────────────────────
function render() {
  renderLang();
  renderCounter();
  renderProducts();
  renderFinalizeBtn();
  renderTestimonials();
  renderMarquee();
  renderNavBadge();
}

function renderLang() {
  const doc = document.documentElement;
  doc.lang = state.lang;
  document.body.dir = state.lang === 'ar' ? 'rtl' : 'ltr';
  $('lang-switcher').textContent = state.lang === 'ar' ? 'FR' : 'AR';

  // Update all data-text elements
  document.querySelectorAll('[data-key]').forEach(el => {
    const key = el.dataset.key;
    const val = T[state.lang][key];
    if (val && typeof val === 'string') el.textContent = val;
  });
  document.querySelectorAll('[data-ph]').forEach(el => {
    const key = el.dataset.ph;
    el.placeholder = T[state.lang][key] || '';
  });

  // Tab buttons
  $('tab-homme').textContent = T[state.lang].tab_homme;
  $('tab-femme').textContent = T[state.lang].tab_femme;
}

function renderNavBadge() {
  $('nav-badge').textContent = t('nav_badge');
}

function renderMarquee() {
  const track = $('marquee-track');
  const text = t('banner');
  track.innerHTML = `<span>${text}</span><span>${text}</span>`;
}

function renderCounter() {
  const n = state.selected.length;
  $('counter-text').textContent = t('counter', n);

  const dots = $('counter-dots');
  dots.innerHTML = state.selected.map((s, i) => {
    const cl = s.gender === 'homme' ? 'filled-homme' : 'filled-femme';
    return `<div class="counter-dot ${cl}">✓</div>`;
  }).join('') + Array(4 - n).fill('<div class="counter-dot"></div>').join('');
}

function renderProducts() {
  const data = state.tab === 'homme' ? ENAS_DATA.homme : ENAS_DATA.femme;
  const grid = $('products-grid');
  const q = state.search.toLowerCase();
  const filtered = q ? data.filter(p =>
    p.name.toLowerCase().includes(q) || p.nameAr.includes(q)
  ) : data;

  if (!filtered.length) {
    grid.innerHTML = `<div class="no-results">🔍 لا توجد نتائج / Aucun résultat</div>`;
    return;
  }

  const isMax = state.selected.length >= 4;

  grid.innerHTML = filtered.map(p => {
    const selIdx = state.selected.findIndex(s => s.id === p.id);
    const isSel = selIdx !== -1;
    const gender = state.tab;
    const selClass = isSel ? (gender === 'homme' ? 'selected-homme' : 'selected-femme') : '';
    const disClass = !isSel && isMax ? 'disabled' : '';
    const imgSrc = PRODUCT_IMAGES[p.img] || '';

    return `
    <div class="product-card ${selClass} ${disClass}" onclick="toggleProduct('${p.id}', '${gender}')">
      <div class="product-img-wrap">
        <img src="${imgSrc}" alt="${p.name}" loading="lazy">
      </div>
      <div class="product-check">✓</div>
      <div class="product-info">
        <div class="product-name">${state.lang === 'ar' && p.nameAr !== p.name ? p.nameAr : p.name}</div>
        ${state.lang === 'fr' && p.nameAr !== p.name ? `<div class="product-name-ar">${p.nameAr}</div>` : ''}
      </div>
    </div>`;
  }).join('');
}

function renderFinalizeBtn() {
  const btn = $('btn-finalize');
  const n = state.selected.length;
  const ready = n === 4;
  btn.disabled = !ready;
  btn.textContent = ready ? t('finalize') : `${t('finalize_dis')} (${n}/4)`;

  const wrap = $('finalize-wrap');
  wrap.classList.toggle('hidden', false);
}

function renderTestimonials() {
  const container = $('testimonials-list');
  container.innerHTML = TESTIMONIALS.map(t2 => `
    <div class="testimonial-card">
      <div class="testimonial-stars">⭐⭐⭐⭐⭐</div>
      <div class="testimonial-text">${state.lang === 'ar' ? t2.text_ar : t2.text_fr}</div>
      <div class="testimonial-name">— ${t2.name}</div>
    </div>
  `).join('');
}

// ─── ACTIONS ──────────────────────────────
function toggleProduct(id, gender) {
  const allData = gender === 'homme' ? ENAS_DATA.homme : ENAS_DATA.femme;
  const product = allData.find(p => p.id === id);
  if (!product) return;

  const idx = state.selected.findIndex(s => s.id === id);
  if (idx !== -1) {
    state.selected.splice(idx, 1);
  } else {
    if (state.selected.length >= 4) return;
    state.selected.push({ ...product, gender });
  }

  renderCounter();
  renderProducts();
  renderFinalizeBtn();

  // Haptic feedback if available
  if (navigator.vibrate) navigator.vibrate(40);
}

function setTab(tab) {
  state.tab = tab;
  state.search = '';
  if ($('search-input')) $('search-input').value = '';

  $('tab-homme').className = 'tab-btn' + (tab === 'homme' ? ' active-homme' : '');
  $('tab-femme').className = 'tab-btn' + (tab === 'femme' ? ' active-femme' : '');

  renderProducts();
}

function setLang(lang) {
  state.lang = lang;
  localStorage.setItem('enas_lang', lang);
  render();
  document.body.dir = lang === 'ar' ? 'rtl' : 'ltr';
}

function toggleLang() {
  setLang(state.lang === 'ar' ? 'fr' : 'ar');
}

function openForm() {
  if (state.selected.length < 4) return;
  renderForm();
  $('form-modal').classList.remove('hidden');
  document.body.style.overflow = 'hidden';
}

function closeForm() {
  $('form-modal').classList.add('hidden');
  document.body.style.overflow = '';
}

function renderForm() {
  // Selected items summary
  const summary = $('selection-summary');
  summary.innerHTML = state.selected.map(p => `
    <div class="sel-item">
      <img src="${PRODUCT_IMAGES[p.img]}" alt="${p.name}">
      <span>${state.lang === 'ar' ? p.nameAr : p.name}</span>
    </div>
  `).join('');

  // Update form labels
  $('label-name').textContent = t('name_label');
  $('label-phone').textContent = t('phone_label');
  $('label-city').textContent = t('city_label');
  $('label-addr').textContent = t('addr_label');
  $('label-note').textContent = t('note_label');
  $('form-title').textContent = t('form_title');
  $('form-sub').textContent = t('form_sub');
  $('info-delivery').textContent = t('free_delivery');
  $('info-cod').textContent = t('cod');
  $('btn-send-wa').textContent = t('send_wa');
  $('inp-name').placeholder = t('name_ph');
  $('inp-phone').placeholder = t('phone_ph');
  $('inp-addr').placeholder = t('addr_ph');
  $('inp-note').placeholder = t('note_ph');

  // City dropdown
  const sel = $('sel-city');
  sel.innerHTML = `<option value="">${t('city_ph')}</option>` +
    ENAS_DATA.cities.map(c => `<option value="${c}">${c}</option>`).join('');
}

function submitOrder() {
  const name = $('inp-name').value.trim();
  const phone = $('inp-phone').value.trim();
  const city = $('sel-city').value;
  const addr = $('inp-addr').value.trim();
  const note = $('inp-note').value.trim();

  if (!name) { alert(t('req_name')); return; }
  if (!phone) { alert(t('req_phone')); return; }
  if (!city) { alert(t('req_city')); return; }
  if (!addr) { alert(t('req_addr')); return; }

  const parfumsText = state.selected.map((p, i) => {
    const emoji = ['1️⃣','2️⃣','3️⃣','4️⃣'][i];
    const genderIcon = p.gender === 'homme' ? '👨 Homme' : '👩 Femme';
    return `${emoji} ${p.name} — ${genderIcon}`;
  }).join('\n');

  const msg = `🌿 *طلب جديد — Ênas Parfums*
━━━━━━━━━━━━━━━━━━━━
👤 الاسم: ${name}
📞 الهاتف: ${phone}
📍 المدينة: ${city}
🏠 العنوان: ${addr}
━━━━━━━━━━━━━━━━━━━━
🛒 *العطور المختارة:*
${parfumsText}
━━━━━━━━━━━━━━━━━━━━
💰 المبلغ الإجمالي: *200 درهم*
🎁 التوصيل: *مجاني* ✅
📦 الدفع عند الاستلام
━━━━━━━━━━━━━━━━━━━━
📝 ملاحظات: ${note || 'لا يوجد'}
🌿 Ênas Parfums — L'Essence de Luxe`;

  const waUrl = `https://wa.me/${WA_NUMBER.replace('+','')}?text=${encodeURIComponent(msg)}`;
  window.open(waUrl, '_blank');
}

// ─── QUIZ LOGIC ────────────────────────
function openQuiz() {
  state.quizStep = 0;
  state.quizAnswers = {};
  state.quizDone = false;
  renderQuiz();
  $('quiz-modal').classList.remove('hidden');
  document.body.style.overflow = 'hidden';
}

function closeQuiz() {
  $('quiz-modal').classList.add('hidden');
  document.body.style.overflow = '';
}

function renderQuiz() {
  const quiz = QUIZ(state.lang);
  const modal = $('quiz-content');
  const progressPct = (state.quizStep / quiz.length) * 100;
  $('quiz-progress-bar').style.width = progressPct + '%';

  if (state.quizDone) {
    // Show results
    const recommendations = getQuizRecommendations();
    modal.innerHTML = `
      <div class="quiz-results">
        <div class="quiz-result-title">${t('quiz_result_title')}</div>
        <div class="quiz-result-grid">
          ${recommendations.map(p => `
            <div class="quiz-result-card">
              <img src="${PRODUCT_IMAGES[p.img]}" alt="${p.name}">
              <span>${state.lang === 'ar' ? p.nameAr : p.name}</span>
            </div>
          `).join('')}
        </div>
        <button class="btn-add-quiz" onclick="addQuizResults()">
          ${t('quiz_add')}
        </button>
        <br><br>
        <button class="quiz-opt" onclick="openQuiz()" style="margin: 0 auto; display:block">
          ${t('quiz_restart')}
        </button>
      </div>`;
    return;
  }

  const q = quiz[state.quizStep];
  modal.innerHTML = `
    <div class="quiz-question">${q.q}</div>
    <div class="quiz-options">
      ${q.a.map((ans, i) => `
        <button class="quiz-opt" onclick="answerQuiz('${q.key}', '${ans}', ${i})">
          ${ans}
        </button>
      `).join('')}
    </div>`;
}

function answerQuiz(key, answer, idx) {
  state.quizAnswers[key] = { answer, idx };
  const quiz = QUIZ(state.lang);
  state.quizStep++;

  if (state.quizStep >= quiz.length) {
    state.quizDone = true;
  }
  renderQuiz();
}

function getQuizRecommendations() {
  const familyMap = { 0: 'floral', 1: 'boise', 2: 'sucre', 3: 'oud', 4: 'frais' };
  const intensityMap = { 0: 'leger', 1: 'modere', 2: 'fort' };
  const occasionMap = { 0: 'quotidien', 1: 'soiree', 2: 'travail', 3: 'romantique' };

  const genderAns = state.quizAnswers.gender?.idx ?? 0;
  const familyAns = state.quizAnswers.family?.idx ?? 0;
  const intensityAns = state.quizAnswers.intensity?.idx ?? 1;
  const occasionAns = state.quizAnswers.occasion?.idx ?? 0;

  let pool = [];
  if (genderAns === 0) pool = ENAS_DATA.homme;
  else if (genderAns === 1) pool = ENAS_DATA.femme;
  else pool = [...ENAS_DATA.homme, ...ENAS_DATA.femme];

  const family = familyMap[familyAns];
  const intensity = intensityMap[intensityAns];
  const occasion = occasionMap[occasionAns];

  // Score each product
  const scored = pool.map(p => {
    let score = 0;
    if (p.family === family) score += 3;
    if (p.intensity === intensity) score += 2;
    if (p.occasion === occasion) score += 1;
    return { ...p, score };
  });

  scored.sort((a, b) => b.score - a.score);
  return scored.slice(0, 4);
}

function addQuizResults() {
  const recs = getQuizRecommendations();
  state.selected = [];
  recs.forEach(p => {
    const gender = ENAS_DATA.homme.some(h => h.id === p.id) ? 'homme' : 'femme';
    state.selected.push({ ...p, gender });
  });
  closeQuiz();
  render();
  scrollTo('products-section');
}

// ─── SCROLL TO SECTION ─────────────────
function scrollToHomme() {
  setTab('homme');
  scrollTo('products-section');
}
function scrollToFemme() {
  setTab('femme');
  scrollTo('products-section');
}

// ─── INIT ──────────────────────────────
function init() {
  // Hide splash after 2s
  setTimeout(() => {
    $('splash').classList.add('hidden');
    setTimeout(() => { $('splash').style.display = 'none'; }, 800);
  }, 2000);

  // Search handler
  $('search-input').addEventListener('input', (e) => {
    state.search = e.target.value;
    renderProducts();
  });

  // Initial render
  render();

  // Tab click handlers
  $('tab-homme').onclick = () => setTab('homme');
  $('tab-femme').onclick = () => setTab('femme');

  // Close modal on overlay click
  $('form-modal').addEventListener('click', (e) => {
    if (e.target === $('form-modal')) closeForm();
  });
}

window.addEventListener('DOMContentLoaded', init);
